mapper.select:
SELECT ryro.*, syosi.specification_id as specificationId, syosi.product_id as productId, (select nick_name from sys_user where user_id = ryro.create_user) as returnUserName FROM sal_yt_return_order ryro LEFT JOIN sal_yt_order_sub_item syosi ON ryro.order_sub_item_id = syosi.id left join sal_yt_order_sub a on a.id =syosi.order_sub_id WHERE -- syosi.order_sub_id = [params.orderSubId] and ryro.is_deleted=0 a.order_id = #{params.orderId} and ryro.is_deleted=0
AND syosi.product_id = #{params.productId}
AND syosi.product_id in (select id from pro_yt_product where code like concat('%',#{params.productCode},'%'))
AND ryro.specification_id = #{params.specificationId}
AND ryro.order_sub_item_id in (select id from sal_yt_order_sub_item where specification_id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{params.specificationName}, '%'))) )
AND ryro.create_time >= #{params.startTime}
AND #{params.endTime} >= ryro.create_time
ORDER BY ryro.create_time DESC

SELECT pyri.id as purchaseItemId, pyri.specification_id as specificationId, pyri.product_id as productId, (select code from pro_yt_product where id = pyri.product_id )as productCode, COUNT(ryro.id) as totalReturnCount, SUM(ryro.return_number) as totalReturnNumber, MAX(first_return.before_return_number) as initialNumber, (MAX(first_return.before_return_number) - SUM(ryro.return_number)) as currentNumber FROM pur_yt_purchase_item pyri LEFT JOIN sal_yt_return_order ryro ON pyri.id = ryro.purchase_item_id AND ryro.is_deleted = 0 LEFT JOIN ( SELECT purchase_item_id, before_return_number, ROW_NUMBER() OVER (PARTITION BY purchase_item_id ORDER BY create_time ASC) as rn FROM sal_yt_return_order WHERE is_deleted = 0 AND type = 2 ) first_return ON first_return.purchase_item_id = pyri.id AND first_return.rn = 1 WHERE pyri.purchase_id = #{params.purchaseId} AND pyri.is_deleted = 0
AND pyri.specification_id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{params.specificationName}, '%')))
AND pyri.product_id in (select id from pro_yt_product where code LIKE CONCAT('%', #{params.productCode}, '%'))
AND ryro.create_time >= #{params.startTime}
AND ryro.create_time <= #{params.endTime}
GROUP BY pyri.id, pyri.specification_id ORDER BY pyri.specification_id

SELECT ryro.*, pyri.id as purchaseItemId, pyri.specification_id as specificationId, pyri.product_id as productId, (select code from pro_yt_product where id = pyri.product_id) as productCode, (select nick_name from sys_user where user_id = ryro.create_user) as returnUserName FROM pur_yt_purchase_item pyri INNER JOIN sal_yt_return_order ryro ON pyri.id = ryro.purchase_item_id AND ryro.is_deleted = 0 WHERE pyri.purchase_id = #{returnOrderParams.purchaseId} AND pyri.is_deleted = 0
AND pyri.specification_id in (select product_specification_id from pro_yt_product_specification_item where category_specification_item_id in (select id from pro_yt_category_specification_item where value LIKE CONCAT('%', #{returnOrderParams.specificationName}, '%')))
AND pyri.product_id in (select id from pro_yt_product where code LIKE CONCAT('%', #{returnOrderParams.productCode}, '%'))
AND ryro.create_time >= #{returnOrderParams.startTime}
AND ryro.create_time <= #{returnOrderParams.endTime}
ORDER BY ryro.create_time DESC
